import { spawnSync } from 'node:child_process';

import { EXECUTABLE_PATH } from '../constants.mjs';

export function runExecutable(argv) {
  const result = spawnSync(EXECUTABLE_PATH, argv, {
    encoding: 'utf8',
    maxBuffer: 10 * 1024 * 1024,
  });

  if (result.error) {
    throw result.error;
  }

  return {
    status: typeof result.status === 'number' ? result.status : 1,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
  };
}

