function rewriteCliLine(line, programName) {
  if (line.startsWith('usage: test2_executable ')) {
    return `usage: ${programName}${line.slice('usage: test2_executable'.length)}`;
  }

  if (line.startsWith('test2_executable:')) {
    return `${programName}${line.slice('test2_executable'.length)}`;
  }

  return line;
}

export function rewriteCliText(text, programName) {
  return text
    .split('\n')
    .map((line) => rewriteCliLine(line, programName))
    .join('\n');
}

export function writeProcessResult(result, programName, rewriteCliOutput = false) {
  const stdout = rewriteCliOutput ? rewriteCliText(result.stdout, programName) : result.stdout;
  const stderr = rewriteCliOutput ? rewriteCliText(result.stderr, programName) : result.stderr;

  if (stdout.length > 0) {
    process.stdout.write(stdout);
  }

  if (stderr.length > 0) {
    process.stderr.write(stderr);
  }

  process.exit(result.status);
}

