import { isHelpInvocation, tryParseCliArgs } from './lib/cli/parse.mjs';
import { getProgramName } from './lib/cli/program.mjs';
import { runExecutable } from './lib/runtime/executable.mjs';
import { writeProcessResult } from './lib/runtime/output.mjs';

const argv = process.argv.slice(2);
const programName = getProgramName(process.argv);
const parsed = tryParseCliArgs(argv);
const result = runExecutable(argv);

if (parsed.kind === 'ok' && result.status === 0) {
  writeProcessResult(result, programName);
}

const shouldRewriteCliOutput = result.status !== 0 || isHelpInvocation(argv);
writeProcessResult(result, programName, shouldRewriteCliOutput);

